mapper.select:
SELECT a.`id`, a.`client_id`, a.`client_name`, a.`third_party_id`, a.`third_program_id`, a.`name`, a.`begin_date`, a.`end_date`, a.`begin_time`, a.`end_time`, a.`weeks`, a.`priority`, a.`state`, a.`type`, a.`tenant`, a.`deleted`, a.`create_by`, a.`create_time`, a.`update_by`, a.`update_time` FROM `program_schedule` a where a.`deleted` = 0
and a.`client_id` = #{param.clientId}
and a.`client_name` like concat('%', #{param.clientName}, '%')
and a.`begin_date` BETWEEN #{param.period.begin} and #{param.period.end}
order by a.`create_time` DESC

SELECT count(*) from `program_schedule` a where a.`deleted` = 0
and a.`client_id` = #{param.clientId}
and a.`client_name` like concat('%', #{param.clientName}, '%')
and a.`begin_date` BETWEEN #{param.period.begin} and #{param.period.end}
